CREATE DATABASE IF NOT EXISTS auto_resource_updater CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE auto_resource_updater;
CREATE TABLE IF NOT EXISTS users (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT, discord_id VARCHAR(32) NOT NULL, discord_username VARCHAR(100) NULL, discord_avatar_url VARCHAR(500) NULL, referral_code CHAR(8) NOT NULL, created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3), PRIMARY KEY (id), UNIQUE KEY uq_users_discord_id (discord_id), UNIQUE KEY uq_users_referral_code (referral_code)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS discount_codes (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT, code VARCHAR(32) NOT NULL, percentage DECIMAL(5,2) NOT NULL, applies_monthly BOOLEAN NOT NULL DEFAULT TRUE, applies_lifetime BOOLEAN NOT NULL DEFAULT TRUE, active BOOLEAN NOT NULL DEFAULT TRUE, max_redemptions INT UNSIGNED NULL, redemption_count INT UNSIGNED NOT NULL DEFAULT 0, expires_at DATETIME(3) NULL, created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), PRIMARY KEY (id), UNIQUE KEY uq_discount_codes_code (code), CONSTRAINT chk_discount_percentage CHECK (percentage > 0 AND percentage <= 100)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS subscriptions (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT, user_id BIGINT UNSIGNED NOT NULL, provider ENUM('paypal','crypto','manual') NOT NULL, provider_subscription_id VARCHAR(127) NULL, plan ENUM('monthly','lifetime') NOT NULL, status ENUM('pending','trialing','active','past_due','cancelled','expired','refunded','suspended') NOT NULL DEFAULT 'pending', base_amount DECIMAL(12,2) NOT NULL, charged_amount DECIMAL(12,2) NOT NULL, currency CHAR(3) NOT NULL DEFAULT 'USD', discount_code VARCHAR(32) NULL, discount_percentage DECIMAL(5,2) NOT NULL DEFAULT 0, current_period_start DATETIME(3) NULL, current_period_end DATETIME(3) NULL, cancel_at_period_end BOOLEAN NOT NULL DEFAULT FALSE, cancelled_at DATETIME(3) NULL, created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3), PRIMARY KEY (id), UNIQUE KEY uq_subscriptions_provider_id (provider, provider_subscription_id), KEY idx_subscriptions_user_status (user_id, status), CONSTRAINT fk_subscriptions_user FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS payments (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT, user_id BIGINT UNSIGNED NOT NULL, subscription_id BIGINT UNSIGNED NULL, provider ENUM('paypal','crypto','manual') NOT NULL, provider_payment_id VARCHAR(127) NOT NULL, status ENUM('created','pending','completed','failed','cancelled','refunded','reversed','expired') NOT NULL DEFAULT 'created', amount DECIMAL(12,8) NOT NULL, currency VARCHAR(12) NOT NULL, paid_at DATETIME(3) NULL, raw_payload JSON NULL, created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3), PRIMARY KEY (id), UNIQUE KEY uq_payments_provider_id (provider, provider_payment_id), KEY idx_payments_user_created (user_id, created_at), CONSTRAINT fk_payments_user FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE, CONSTRAINT fk_payments_subscription FOREIGN KEY (subscription_id) REFERENCES subscriptions(id) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS free_trials (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT, user_id BIGINT UNSIGNED NOT NULL, status ENUM('active','expired','cancelled') NOT NULL DEFAULT 'active', starts_at DATETIME(3) NOT NULL, expires_at DATETIME(3) NOT NULL, created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), PRIMARY KEY (id), UNIQUE KEY uq_free_trials_user (user_id), KEY idx_free_trials_status_expiry (status, expires_at), CONSTRAINT fk_free_trials_user FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS affiliate_accounts (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT, user_id BIGINT UNSIGNED NOT NULL, status ENUM('pending','approved','rejected','suspended') NOT NULL DEFAULT 'pending', approved_at DATETIME(3) NULL, created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3), PRIMARY KEY (id), UNIQUE KEY uq_affiliate_accounts_user (user_id), CONSTRAINT fk_affiliate_accounts_user FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS referrals (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT, affiliate_user_id BIGINT UNSIGNED NOT NULL, referred_user_id BIGINT UNSIGNED NOT NULL, referral_code CHAR(8) NOT NULL, plan ENUM('monthly','lifetime') NULL, status ENUM('pending','qualified','inactive','not_applicable') NOT NULL DEFAULT 'pending', commission_amount DECIMAL(12,2) NOT NULL DEFAULT 0, registered_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), qualifies_at DATETIME(3) NULL, qualified_at DATETIME(3) NULL, updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3), PRIMARY KEY (id), UNIQUE KEY uq_referrals_referred_user (referred_user_id), KEY idx_referrals_affiliate_status (affiliate_user_id, status), CONSTRAINT fk_referrals_affiliate FOREIGN KEY (affiliate_user_id) REFERENCES users(id) ON DELETE CASCADE, CONSTRAINT fk_referrals_referred FOREIGN KEY (referred_user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS affiliate_ledger (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT, affiliate_user_id BIGINT UNSIGNED NOT NULL, referral_id BIGINT UNSIGNED NULL, kind ENUM('pending','earned','withdrawal','reversal','adjustment') NOT NULL, amount DECIMAL(12,2) NOT NULL, description VARCHAR(255) NULL, available_at DATETIME(3) NULL, created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), PRIMARY KEY (id), KEY idx_affiliate_ledger_user_kind (affiliate_user_id, kind, created_at), CONSTRAINT fk_affiliate_ledger_user FOREIGN KEY (affiliate_user_id) REFERENCES users(id) ON DELETE CASCADE, CONSTRAINT fk_affiliate_ledger_referral FOREIGN KEY (referral_id) REFERENCES referrals(id) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS withdrawal_requests (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT, affiliate_user_id BIGINT UNSIGNED NOT NULL, amount DECIMAL(12,2) NOT NULL, status ENUM('pending','processing','paid','rejected','cancelled') NOT NULL DEFAULT 'pending', destination JSON NULL, provider_reference VARCHAR(127) NULL, requested_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), processed_at DATETIME(3) NULL, PRIMARY KEY (id), KEY idx_withdrawals_user_status (affiliate_user_id, status), CONSTRAINT fk_withdrawals_user FOREIGN KEY (affiliate_user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS crypto_deposits (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT, user_id BIGINT UNSIGNED NOT NULL, plan ENUM('monthly','lifetime') NOT NULL, asset ENUM('USDT','BTC') NOT NULL, network VARCHAR(32) NOT NULL, address VARCHAR(255) NOT NULL, qr_code TEXT NOT NULL, expected_crypto_amount DECIMAL(24,8) NULL, expected_usd_amount DECIMAL(12,2) NOT NULL, discount_code VARCHAR(32) NULL, status ENUM('pending','confirming','completed','expired','failed') NOT NULL DEFAULT 'pending', provider_payment_id VARCHAR(127) NULL, expires_at DATETIME(3) NOT NULL, created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3), PRIMARY KEY (id), UNIQUE KEY uq_crypto_provider_payment (provider_payment_id), KEY idx_crypto_user_status (user_id, status), CONSTRAINT fk_crypto_deposits_user FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS paypal_webhook_events (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT, paypal_event_id VARCHAR(127) NOT NULL, event_type VARCHAR(100) NOT NULL, resource_id VARCHAR(127) NULL, processing_status ENUM('received','processed','ignored','failed') NOT NULL DEFAULT 'received', payload JSON NOT NULL, error_message TEXT NULL, received_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), processed_at DATETIME(3) NULL, PRIMARY KEY (id), UNIQUE KEY uq_paypal_webhook_event (paypal_event_id), KEY idx_paypal_events_type_status (event_type, processing_status)) ENGINE=InnoDB;
INSERT INTO discount_codes (code, percentage, applies_monthly, applies_lifetime) VALUES ('WELCOME', 10.00, TRUE, TRUE) ON DUPLICATE KEY UPDATE percentage = VALUES(percentage), active = TRUE;

